"""Vanish dependency construction from resolved particle requirements."""

from __future__ import annotations

from typing import override

from operation_graph_optimization import algorithm, graph


class Collector:
    """Retain lifetime candidates until all position dependencies are known."""

    def __init__(self, calculated: graph.Graph):
        """Share the graph whose occurrence identities appear in requirements."""
        self.graph: graph.Graph = calculated
        self.candidates: dict[int, set[int]] = {}
        self.vacates: dict[int, int] = {}

    def _use(self, particle: int, occurrence: int, dependencies: list[int]):
        del dependencies
        self.candidates.setdefault(particle, set()).add(occurrence)

    def observe(self, occurrence: int, particles: tuple[int, ...], vacated: int | None):
        """Include actual quality uses, direct movement, and selected Vacation."""
        dependencies = list(self.graph.dependencies(occurrence))
        for particle in particles:
            if particle != vacated:
                self._use(particle, occurrence, dependencies)
        if vacated is not None:
            self.vacates[vacated] = occurrence
            self._use(vacated, occurrence, dependencies)

    def finish(self) -> dict[int, int]:
        """Append Vanishes without changing position setters or readers."""
        result: dict[int, int] = {}
        for particle in self.vacates:
            candidates = self.candidates.pop(particle)
            result[particle] = self.graph.append(
                algorithm.compare(self.graph, candidates)
            )
        return result


class DirectPruning(Collector):
    """Retire a previous use when the new use directly depends on it."""

    @override
    def _use(self, particle: int, occurrence: int, dependencies: list[int]):
        candidates = self.candidates.setdefault(particle, set())
        candidates.difference_update(dependencies)
        candidates.add(occurrence)


class Incremental(Collector):
    """Maintain the exact antichain after every particle requirement."""

    @override
    def _use(self, particle: int, occurrence: int, dependencies: list[int]):
        del dependencies
        candidates = self.candidates.setdefault(particle, set())
        covered: list[int] = []
        for previous in candidates:
            if self.graph.reaches(occurrence, previous):
                covered.append(previous)
        candidates.difference_update(covered)
        candidates.add(occurrence)

sources.vanish_workloads.py:
"""Resolve lifetime inputs independently of dependency calculation."""

from __future__ import annotations

import dataclasses
import random

from operation_graph_optimization import (
    algorithm,
    order_variants,
    state_workloads,
    workloads,
)


@dataclasses.dataclass(slots=True)
class Step:
    """Position requirements and the original particles actually required."""

    operation: algorithm.Operation
    particles: tuple[int, ...]
    vacated: int | None
    moved: int | None = None
    ordinary_occupants: tuple[int, ...] = ()


def resolve(operations: list[algorithm.Operation]) -> list[Step]:
    """Track selected identities without consulting calculated dependencies."""
    occupied: dict[int, int] = {}
    result: list[Step] = []
    for occurrence, operation in enumerate(operations):
        required = set(operation.creators)
        observed = tuple(occupied[position] for position in operation.occupied)
        vacated = None
        moved = None
        if operation.empty is not None:
            particle = occupied.pop(operation.empty)
            if operation.fill is None:
                vacated = particle
            else:
                occupied[operation.fill] = particle
                required.add(particle)
                moved = particle
        elif operation.fill is not None:
            occupied[operation.fill] = occurrence
        result.append(Step(operation, tuple(required), vacated, moved, observed))
    return result


def independent_uses(seed: int, steps: int, width: int) -> list[algorithm.Operation]:
    """Interleave constructor accesses to distinct implied child positions."""
    randomizer = random.Random(seed)  # noqa: S311 - Reproducible experiments.
    operations = [algorithm.Operation(fill=0, defines=tuple(range(1, width + 1)))]
    occupied: set[int] = set()
    for _ in range(steps):
        position = randomizer.randrange(1, width + 1)
        if position in occupied:
            operations.append(algorithm.Operation(empty=position, creators=(0,)))
            occupied.remove(position)
        else:
            operations.append(algorithm.Operation(fill=position, creators=(0,)))
            occupied.add(position)
    # Automatic destruction selects remaining children without written references.
    positions = [0, *sorted(occupied)]
    randomizer.shuffle(positions)
    operations.extend(algorithm.Operation(empty=position) for position in positions)
    return operations


def generate(family: str, seed: int, steps: int, width: int) -> list[Step]:
    """Prepare complete inputs before timing either graph construction phase."""
    groups: dict[int, int] = {}
    if family == "wide":
        operations = independent_uses(seed, steps, width)
    elif family == "implied":
        operations = list(workloads.implied_uses(seed, steps, width))
    elif family == "movement":
        operations = list(workloads.overlapping_moves(seed, steps, width))
    elif family == "written":
        operations = list(workloads.preceding_uses(seed, steps, width))
    elif family == "local":
        operations = workloads.random_program(seed, steps, width).operations
    else:
        operations, groups = state_workloads.generate(
            seed,
            steps,
            width=width,
            depth=6,
            branching=2,
            distribution="growth"
            if family in {"growth", "growth_closed"}
            else "balanced",
        )
    if family == "growth_closed":
        occupied: set[int] = set()
        for operation in operations:
            if operation.empty is not None:
                occupied.remove(operation.empty)
            if operation.fill is not None:
                occupied.add(operation.fill)
        positions = sorted(occupied)
        random.Random(seed + 211).shuffle(positions)  # noqa: S311 - Reproducible selection order.
        groups[len(operations)] = len(positions)
        operations.extend(algorithm.Operation(empty=position) for position in positions)
    reordered, _, _ = order_variants.reorder(operations, groups, seed + 101)
    return resolve(reordered)

sources.vanish_integration_test.py:
from __future__ import annotations

import itertools

import pytest

from define.compiler import driver
from operation_graph_optimization import (
    algorithm,
    vanish,
    vanish_algorithm,
    vanish_workloads,
    workloads,
)


def _check(
    steps: list[vanish_workloads.Step],
    implementation: type[vanish.Collector | vanish_algorithm.Calculator],
):
    calculator = algorithm.Calculator()
    collector = implementation(calculator.graph)
    ancestors: list[set[int]] = []
    all_uses: dict[int, set[int]] = {}
    destroyed: set[int] = set()
    for step in steps:
        occurrence = calculator.add(step.operation)
        reached = set(calculator.graph.dependencies(occurrence))
        for dependency in calculator.graph.dependencies(occurrence):
            reached.update(ancestors[dependency])
        ancestors.append(reached)
        for particle in step.particles:
            all_uses.setdefault(particle, set()).add(occurrence)
        if step.vacated is not None:
            destroyed.add(step.vacated)
            all_uses.setdefault(step.vacated, set()).add(occurrence)
        if isinstance(collector, vanish_algorithm.Calculator):
            collector.observe(
                occurrence,
                step.operation.creators,
                step.moved,
                step.vacated,
                step.ordinary_occupants,
            )
        else:
            collector.observe(occurrence, step.particles, step.vacated)
    result = collector.finish()
    assert set(result) == destroyed
    for particle, occurrence in result.items():
        expected = set(all_uses[particle])
        for candidate in all_uses[particle]:
            expected.difference_update(ancestors[candidate])
        assert set(calculator.graph.dependencies(occurrence)) == expected
    return calculator.graph, result


@pytest.mark.parametrize(
    "implementation",
    [
        vanish.Collector,
        vanish.DirectPruning,
        vanish.Incremental,
        vanish_algorithm.Calculator,
    ],
)
@pytest.mark.parametrize("seed", range(5))
def test_random_real_source(
    implementation: type[vanish.Collector | vanish_algorithm.Calculator], seed: int
):
    program = workloads.random_program(seed, 70, 8)
    validated = driver.Driver().validate_source(program.source).program_validation
    assert validated.all_exceptions == []
    assert validated.all_diagnostics == []
    _ = _check(vanish_workloads.resolve(program.operations), implementation)


@pytest.mark.parametrize(
    "implementation",
    [
        vanish.Collector,
        vanish.DirectPruning,
        vanish.Incremental,
        vanish_algorithm.Calculator,
    ],
)
@pytest.mark.parametrize(
    "family",
    [
        "local",
        "movement",
        "implied",
        "written",
        "wide",
        "state",
        "growth",
        "growth_closed",
    ],
)
@pytest.mark.parametrize("seed", range(3))
def test_reordered_valid_inputs(
    implementation: type[vanish.Collector | vanish_algorithm.Calculator],
    family: str,
    seed: int,
):
    _ = _check(vanish_workloads.generate(family, seed, 70, 8), implementation)


@pytest.mark.parametrize(
    "implementation",
    [
        vanish.Collector,
        vanish.DirectPruning,
        vanish.Incremental,
        vanish_algorithm.Calculator,
    ],
)
@pytest.mark.parametrize("kind", ["constructor", "interface", "destructor"])
def test_actual_quality_access_outlives_vacancy(
    implementation: type[vanish.Collector | vanish_algorithm.Calculator], kind: str
):
    interface = kind == "interface"
    destructor = kind == "destructor"
    reference = "position<marker>" if interface else "position</marker>"
    declarations = (
        "    define the position<marker>."
        if interface
        else "    it also assigns the position</marker>."
    )
    trigger = "being destroyed" if destructor else "created"
    source = f"""define the potential position<my.domain.com:my_lib:/marker>.
define the potential action<my.domain.com:my_lib:/work> {{
{declarations}
    it happens when {{
        this particle is {trigger}.
    }} and it does {{
        create a particle in {reference}.
        destroy the particle in {reference}.
    }}
}}
define the potential action<my.domain.com:my_lib:/test> {{
    it happens when {{
        this particle is created.
    }} and it does {{
        define the position<parent> {{
            it may only contain particles where {{
                it has the action</work>.
            }}
        }}
        create a particle in position<parent>.
        destroy the particle in position<parent>.
    }}
}}
"""
    validated = driver.Driver().validate_source(source).program_validation
    assert validated.all_exceptions == []
    assert validated.all_diagnostics == []
    operations = [algorithm.Operation(fill=0, defines=(1,))]
    if destructor:
        operations.append(algorithm.Operation(empty=0))
    operations.extend(
        [
            algorithm.Operation(fill=1, creators=(0,)),
            algorithm.Operation(empty=1, creators=(0,)),
        ]
    )
    if not destructor:
        operations.append(algorithm.Operation(empty=0))
    steps = vanish_workloads.resolve(operations)
    calculated, vanishes = _check(steps, implementation)
    vacancy = 1 if destructor else 3
    last_use = 3 if destructor else 2
    assert set(calculated.dependencies(vanishes[0])) == {vacancy, last_use}
    assert not calculated.reaches(vacancy, last_use)
    schedules: list[dict[int, int]] = []
    for order in itertools.permutations(range(len(calculated))):
        indexes = {occurrence: index for index, occurrence in enumerate(order)}
        valid = True
        for occurrence in order:
            for dependency in calculated.dependencies(occurrence):
                if indexes[dependency] > indexes[occurrence]:
                    valid = False
        if valid:
            schedules.append(indexes)
            assert indexes[last_use] < indexes[vanishes[0]]
    assert any(order[vacancy] < order[last_use] for order in schedules)


