"""Vanish Collection specialized for ordered direct Moves."""

from __future__ import annotations

from typing import final

from operation_graph_optimization import algorithm, graph


@final
class Calculator:
    """Calculate Vanishes without changing existing position dependencies."""

    def __init__(self, calculated: graph.Graph):
        """Share occurrence identities with the position-dependency graph."""
        self.graph = calculated
        self.candidates: dict[int, set[int]] = {}
        self.last_moves: dict[int, int] = {}
        self.vacates: dict[int, int] = {}

    def observe(
        self,
        occurrence: int,
        quality_particles: tuple[int, ...],
        moved: int | None,
        vacated: int | None,
        ordinary_occupants: tuple[int, ...] = (),
    ):
        """Record actual quality uses, direct movement, and selected Vacation."""
        if quality_particles and ordinary_occupants:
            covered = set(ordinary_occupants)
            quality_particles = tuple(
                particle for particle in quality_particles if particle not in covered
            )
        if quality_particles or vacated is not None:
            dependencies = self.graph.dependencies(occurrence)
            for particle in quality_particles:
                candidates = self.candidates.setdefault(particle, set())
                candidates.difference_update(dependencies)
                candidates.add(occurrence)
            if vacated is not None:
                self.vacates[vacated] = occurrence
                candidates = self.candidates.setdefault(vacated, set())
                candidates.difference_update(dependencies)
                candidates.add(occurrence)
        if moved is not None:
            self.last_moves[moved] = occurrence

    def finish(self) -> dict[int, int]:
        """Append each selected particle's Vanish after its maximal candidates."""
        result: dict[int, int] = {}
        for particle in self.vacates:
            candidates = self.candidates.pop(particle)
            last_move = self.last_moves.pop(particle, None)
            if last_move is not None:
                candidates.add(last_move)
            result[particle] = self.graph.append(
                algorithm.compare(self.graph, candidates)
            )
        return result

sources.integrated_variants.py:
"""Integrated alternatives kept separate from the recommended algorithm."""

from __future__ import annotations

from typing import TYPE_CHECKING, override

from operation_graph_optimization.integrated import algorithm

if TYPE_CHECKING:
    from operation_graph_optimization import vanish_workloads


class Direct(algorithm.Calculator):
    """Share Comparison's result instead of Collection's candidates."""

    @override
    def add(self, operation: algorithm.Operation) -> int:
        """Calculate one operation and maintain its position and particle uses."""
        candidates = self._collect(operation)
        dependencies = algorithm.compare(self.graph, candidates)
        occurrence = self.graph.append(dependencies)
        self._record(operation, occurrence, candidates)
        self._observe(operation, occurrence, dependencies)
        return occurrence


class Unpruned(algorithm.Calculator):
    """Defer all particle-use pruning until final Comparison."""

    @override
    def _observe(
        self,
        operation: algorithm.Operation,
        occurrence: int,
        predecessors: set[int] | list[int],
    ):
        super()._observe(operation, occurrence, [])


class Indexed(algorithm.Calculator):
    """Include terminal Vanishes in the reverse reachability index."""

    @override
    def finish(self) -> dict[int, int]:
        """Append the same Vanishes using ordinary indexed insertion."""
        result: dict[int, int] = {}
        for particle in self._vacates:
            candidates = self._uses.pop(particle)
            moved = self._last_moves.pop(particle, None)
            if moved is not None:
                candidates.add(moved)
            result[particle] = self.graph.append(
                algorithm.compare(self.graph, candidates)
            )
        return result


def convert(step: vanish_workloads.Step) -> algorithm.Operation:
    """Resolve the same workload into the complete algorithm's input type."""
    operation = step.operation
    return algorithm.Operation(
        occupied=operation.occupied,
        fill=operation.fill,
        empty=operation.empty,
        creators=operation.creators,
        defines=operation.defines,
        quality_particles=operation.creators,
        ordinary_occupants=step.ordinary_occupants,
        moved=step.moved,
        vacated=step.vacated,
    )

